#include "Servo.h"
Servo servo;

int pos; // угол поворота серво

void setup() {
  servo.attach(9);
}

void loop() {
  /// плавное управление с помощью цикла for ///

  // плавный поворот от 0 до 90 градусов
  for (pos = 0; pos <= 90; pos = pos + 1) {
    servo.write(pos);
    delay(20); // изменив значение можно ускорить или замедлить поворот
  }

  // плавный поворот от 90 до 0 градусов
  for (pos = 90; pos >= 0; pos = pos + 1) {
    servo.write(pos);
    delay(20);
  }

  /// плавное управление с помощью цикла while ///

  // плавный поворот от 0 до 45 градусов
  while (pos < 45) {
    pos = pos + 5; // серво поворачивается при каждом шаге на 5 градусов
    servo.write(pos);
    delay(20); // изменив значение можно ускорить или замедлить поворот
  }

  // плавный поворот от 45 до 0 градусов
    while (pos > 0) {
    pos = pos - 5;
    servo.write(pos);
    delay(20);
  }

}
